function BeginnerAssembleMallEventSpecialDialog:Refresh(config)
	self.config = config
	self.dojo = BeginnerUtils.GetBeginnerDojo()
	self.data = self.dojo:GetGiftInfo()
	self:RefreshShow()
end

function BeginnerAssembleMallEventSpecialDialog:RefreshShow()
	local count = #self.data
	if not self.ScrollView.IsListViewInit then
		self.ScrollView:InitListView(count, Bind(self, self.OnRefreshCellIndex))
	else
		GameUtils.ReloadData(self.ScrollView, count)
	end
end

function BeginnerAssembleMallEventSpecialDialog:OnRefreshCellIndex(listView, index)
	if index < 0 or index >= #self.data then
		return
	end
	local cell = listView:NewListViewItem(ItemCell)
	local tableCellEnv = CfUtils.GetLuaScr(cell, NodeCellPath)
	if tableCellEnv then
		tableCellEnv:RefreshCell(OverseaStoreConstants.StoreType.BeginnerGift,self.data[index + 1])
		tableCellEnv:SetCallBackAndIndex(Bind(self,self.OnBuyRefresh),index + 1)
	end
	return cell
end

function BeginnerAssembleMallEventSpecialDialog:OnBuyRefresh()
	self.data = self.dojo:GetGiftInfo()
	self:RefreshShow()
	BeginnerUtils.RefreshRedPoint(self.config.type)
end

function BeginnerAssembleMallEventSpecialDialog:RefreshTopGoods()
