end

function BeginnerAssembleMallEventSpecialDialog:RefreshTimeShow()
	local curTime = GameUtils.GetServerTime() or os.time()
	local time =  math.max(0, self.dojo.mallLeftSeconds - curTime)
	CfUtils.FillText(self.TextTime2,CfUtils.GetTimeHMS4(time))
end

